NORMS={}
def add(sid,keys,pages,text,result,limit='No clinical clearance; no additional numeric coefficient or universal schedule inferred.'):
    for key in keys.split(): NORMS[(sid,key)]=dict(source_id=sid,condition_key=key,physical_pages=pages,independent_primary_norm=text,permitted_result=result,result_limit=limit)
